struct sk_buff *reassemble_ipv6_fragments(struct nf_ct_frag6_queue *fq, struct net_device *dev) {
    struct sk_buff *skb = NULL;
    unsigned int payload_len;
    int err;

    if (!fq || !dev) {
        return NULL;
    }

    payload_len = fq->payload_len;

    skb = alloc_skb(payload_len, GFP_ATOMIC);
    if (!skb) {
        pr_debug("Memory allocation failure during IPv6 reassembly.\n");
        return NULL;
    }

    if (fq->first && fq->first->more) {
        pr_debug("First fragment is itself fragmented.\n");
        goto out;
    }

    skb->len = 0;
    skb->data_len = 0;
    skb->truesize = 0;
    skb_shrink(skb);

    err = ip6_frag_reasm(skb, fq, dev);
    if (err < 0) {
        pr_debug("Error reassembling IPv6 fragments.\n");
        goto out;
    }

    return skb;

