    return NULL;
}

struct sk_buff *reassemble_ipv6_fragments(struct nf_ct_frag6_queue *fq,
                                          struct net_device *dev) {
    struct sk_buff *skb;
    int payload_len;
    int i;

    if (!fq || !dev) {
        return NULL;
    }

    payload_len = 0;
    for (i = 0; i < fq->q.pf.holes; i++) {
        payload_len += fq->q.fragments[i]->len;
    }

    if (payload_len > IPV6_MAX_PAYLOAD) {
        pr_debug("IPv6 payload too large for reassembly\n");
        return NULL;
    }

    skb = alloc_skb(payload_len, GFP_ATOMIC);
    if (!skb) {
        pr_debug("Failed to allocate memory for reassembled IPv6 packet\n");
        return NULL;
    }

    for (i = 0; i < fq->q.pf.holes; i++) {
        struct sk_buff *fragment = fq->q.fragments[i];
        int len = fragment->len;

        if (skb_put_data(skb, fragment->data, len) < 0) {
            kfree_skb(skb);
            pr_debug("Failed to append fragment data to reassembled IPv6 packet\n");
            return NULL;
        }
    }

    skb->dev = dev;
    skb->protocol = htons(ETH_P_IPV6);
    skb->pkt_type = PACKET_HOST;

    return skb;
}

struct sk_buff *reassemble_ipv6_fragments(struct nf_ct_frag6_queue *fq, struct net_device *dev)
{
    struct sk_buff *skb;
    struct ipv6hdr *ipv6h;
    int payload_len;
    int ret;

    if (!fq || !dev) {
        return NULL;
    }

    payload_len = nf_ct_frag6_queue_payload_len(fq);
    if (payload_len < 0) {
        return NULL;
    }

    skb = alloc_skb(payload_len + sizeof(struct ipv6hdr), GFP_ATOMIC);
    if (!skb) {
        return NULL;
    }

    skb_reserve(skb, sizeof(struct ipv6hdr));

    ret = nf_ct_frag6_queue_build_skb(fq, skb);
    if (ret < 0) {
        kfree_skb(skb);
        return NULL;
    }

    ipv6h = skb_push(skb, sizeof(struct ipv6hdr));
    memset(ipv6h, 0, sizeof(*ipv6h));

    ipv6h->version = 6;
    ipv6h->payload_len = htons(payload_len);
    ipv6h->nexthdr = fq->frag_list->nh;
    ipv6h->saddr = fq->frag_list->ipv6h->saddr;
    ipv6h->daddr = fq->frag_list->ipv6h->daddr;

    ipv6h->hop_limit = fq->frag_list->ipv6h->hop_limit;

    skb->dev = dev;
    skb->pkt_type = PACKET_HOST;

    nf_ct_frag6_queue_free(fq);

    return skb;
}

struct sk_buff *reassemble_ipv6_fragments(struct nf_ct_frag6_queue *fq, struct net_device *dev)
{
    struct sk_buff *skb = NULL;

    if (!fq || !dev) {
        return NULL;
    }

    if (fq->fragments == NULL || list_empty(&fq->list)) {
        return NULL;
    }

    skb = skb_clone(fq->fragments, GFP_ATOMIC);
    if (!skb) {
        return NULL;
    }

    skb_shinfo(skb)->frag_list = fq->fragments->next;
    skb_shinfo(skb)->nr_frags = 0;

    skb->dev = dev;
    skb->protocol = htons(ETH_P_IPV6);

    ip6_recalc_flowlabel(skb);
    ip6_hdr(skb)->payload_len = htons(skb->len - sizeof(struct ipv6hdr));

    return skb;
}

struct sk_buff *reassemble_ipv6_fragments(struct nf_ct_frag6_queue *fq, struct net_device *dev) {
    struct sk_buff *skb;
    int payload_len;
    int i;

    if (!fq || !dev) {
        return NULL;
    }

    payload_len = 0;
    for (i = 0; i < fq->q.pf.hole; i++) {
        payload_len += fq->q.fragments[i]->len;
    }

    if (payload_len > IPV6_MAX_PAYLOAD) {
        pr_debug("IPv6 reassembly: oversized payload\n");
        return NULL;
    }

    skb = alloc_skb(payload_len, GFP_ATOMIC);
    if (!skb) {
        pr_debug("IPv6 reassembly: memory allocation failure\n");
        return NULL;
    }

    for (i = 0; i < fq->q.pf.hole; i++) {
        struct sk_buff *fragment = fq->q.fragments[i];
        if (!fragment) {
            pr_debug("IPv6 reassembly: missing fragment\n");
            kfree_skb(skb);
            return NULL;
        }

        skb_add_data(skb, fragment->data, fragment->len);
    }

    skb->dev = dev;
    skb->protocol = htons(ETH_P_IPV6);
    skb->len = payload_len;

    return skb;
}
